function validate([initialCurrency, pairs1, rates1, pairs2, rates2]) {
  const name = /^[A-Z]{1,3}$/;
  if (!name.test(initialCurrency)) return 'initialCurrency is 1 to 3 uppercase letters.';
  const reached = [];
  for (const [pairs, rates, label] of [[pairs1, rates1, 'day 1'], [pairs2, rates2, 'day 2']]) {
    if (pairs.length < 1 || pairs.length > 10) return `Each day needs 1 to 10 pairs (${label} has ${pairs.length}).`;
    if (rates.length !== pairs.length) return `Give ${label} exactly one rate per pair.`;
    const parent = new Map();
    const find = (x) => { while (parent.get(x) !== x) x = parent.get(x); return x; };
    for (let i = 0; i < pairs.length; i++) {
      const pair = pairs[i];
      if (pair.length !== 2 || !pair.every(c => name.test(c))) return 'Each pair is two currency names of 1 to 3 uppercase letters.';
      if (!(rates[i] >= 1 && rates[i] <= 10)) return 'Every rate is between 1.0 and 10.0.';
      for (const c of pair) if (!parent.has(c)) parent.set(c, c);
      const a = find(pair[0]);
      const b = find(pair[1]);
      if (a === b) return `The ${label} pairs must not form a cycle.`;
      parent.set(a, b);
    }
    const amount = new Map([[initialCurrency, 1]]);
    for (let round = 0; round <= pairs.length; round++) {
      pairs.forEach(([a, b], i) => {
        if (amount.has(a) && !amount.has(b)) amount.set(b, amount.get(a) * rates[i]);
        if (amount.has(b) && !amount.has(a)) amount.set(a, amount.get(b) / rates[i]);
      });
    }
    reached.push(amount);
  }
  let best = 1;
  for (const [currency, held] of reached[0]) if (reached[1].has(currency)) best = Math.max(best, held / reached[1].get(currency));
  if (best > 5e10 * (1 + 1e-9)) return 'These rates allow more than 5 * 10^10; the answer must stay within that.';
  return null;
}

