function maxAmount(initialCurrency, pairs1, rates1, pairs2, rates2) {
  const explore = (pairs, rates) => {
    const graph = new Map();
    const addEdge = (from, to, rate) => {
      if (!graph.has(from)) {
        graph.set(from, []);
      }
      graph.get(from).push([to, rate]);
    };
    for (let i = 0; i < pairs.length; i++) {
      const [from, to] = pairs[i];
      addEdge(from, to, rates[i]);
      addEdge(to, from, 1 / rates[i]);
    }
    const amount = new Map();
    const dfs = (currency, value) => {
      amount.set(currency, value);
      for (const [next, rate] of graph.get(currency) ?? []) {
        if (!amount.has(next)) {
          dfs(next, value * rate);
        }
      }
    };
    dfs(initialCurrency, 1);
    return amount;
  };

  const day1 = explore(pairs1, rates1);
  const day2 = explore(pairs2, rates2);
  let best = 1;
  for (const [currency, held] of day1) {
    if (day2.has(currency)) {
      best = Math.max(best, held / day2.get(currency));
    }
  }
  return best;
}

