function maxAmount(initialCurrency, pairs1, rates1, pairs2, rates2) {
  // Bellman-Ford style: relax every swap in both directions until no holding grows.
  // Day 2 starts from every day-1 holding at once, since you may end day 1 in any of them.
  const relax = (holding, pairs, rates) => {
    let changed = true;
    while (changed) {
      changed = false;
      pairs.forEach(([a, b], i) => {
        for (const [from, to, rate] of [[a, b, rates[i]], [b, a, 1 / rates[i]]]) {
          if (!holding.has(from)) continue;
          const value = holding.get(from) * rate;
          if (!holding.has(to) || value > holding.get(to) * (1 + 1e-12)) {
            holding.set(to, value);
            changed = true;
          }
        }
      });
    }
    return holding;
  };
  const afterDay1 = relax(new Map([[initialCurrency, 1]]), pairs1, rates1);
  return relax(new Map(afterDay1), pairs2, rates2).get(initialCurrency);
}

