function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const makeName = () => {
    let name = '';
    const length = 1 + pick(3);
    for (let j = 0; j < length; j++) name += letters[pick(large ? 26 : 6)];
    return name;
  };
  // A random forest of swaps over the shared pool, so the two days overlap in currencies.
  const makeDay = (pool, edges) => {
    const parent = pool.map((_, i) => i);
    const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
    const pairs = [];
    const rates = [];
    while (pairs.length < edges) {
      const a = pick(pool.length);
      const b = pick(pool.length);
      if (find(a) === find(b)) continue;
      parent[find(a)] = find(b);
      pairs.push([pool[a], pool[b]]);
      rates.push((10 + pick(91)) / 10);
    }
    return [pairs, rates];
  };
  const reach = (start, pairs, rates) => {
    const amount = new Map([[start, 1]]);
    for (let round = 0; round <= pairs.length; round++) {
      pairs.forEach(([a, b], i) => {
        if (amount.has(a) && !amount.has(b)) amount.set(b, amount.get(a) * rates[i]);
        if (amount.has(b) && !amount.has(a)) amount.set(a, amount.get(b) / rates[i]);
      });
    }
    return amount;
  };
  for (;;) {
    const names = new Set();
    // Large inputs use 10 swaps a day over 11 currencies: two spanning trees, so every currency is shared.
    const count = large ? 11 : 2 + pick(5);
    while (names.size < count) names.add(makeName());
    const pool = [...names];
    let initialCurrency = pool[0];
    if (!large && rand() < 0.1) {
      do initialCurrency = makeName(); while (names.has(initialCurrency));
    }
    const [pairs1, rates1] = makeDay(pool, large ? 10 : 1 + pick(Math.min(5, pool.length - 1)));
    const [pairs2, rates2] = makeDay(pool, large ? 10 : 1 + pick(Math.min(5, pool.length - 1)));
    // Keep the answer within the guaranteed 5 * 10^10.
    const day1 = reach(initialCurrency, pairs1, rates1);
    const day2 = reach(initialCurrency, pairs2, rates2);
    let best = 1;
    for (const [currency, held] of day1) if (day2.has(currency)) best = Math.max(best, held / day2.get(currency));
    if (best <= 5e10) return [initialCurrency, pairs1, rates1, pairs2, rates2];
  }
}
